## Corrected Function

```go
// TransformItems applies a transformation function to a slice of items with retry logic.
// Returns the transformed items or an error if any item fails after max retries.
func TransformItems(ctx context.Context, items []string, transform func(string) (string, error), maxRetries int) ([]string, error) {
	if maxRetries < 0 {
		return nil, fmt.Errorf("maxRetries must be non-negative, got %d", maxRetries)
	}

	result := make([]string, 0, len(items))

	for _, item := range items {
		var transformed string
		var err error
		succeeded := false

		// Retry loop with proper error tracking
		for attempt := 0; attempt <= maxRetries; attempt++ {
			transformed, err = transform(item)
			if err == nil {
				succeeded = true
				break
			}

			// Don't sleep after the last failed attempt
			if attempt < maxRetries {
				select {
				case <-time.After(time.Duration(attempt+1) * time.Second):
					// Continue to next retry
				case <-ctx.Done():
					return nil, fmt.Errorf("context cancelled while processing item %q: %w", item, ctx.Err())
				}
			}
		}

		// Check if transformation succeeded after all retries
		if !succeeded {
			return nil, fmt.Errorf("failed to process item %q after %d retries: %w", item, maxRetries, err)
		}

		result = append(result, transformed)
	}

	return result, nil
}
```

## Key Fixes Applied

1. **Variable Scope Issue**: Introduced a `succeeded` boolean flag to track transformation success outside the retry loop, eliminating the scope problem with the `err` variable.

2. **Error Handling**: The function now properly returns an error when any item fails after all retries, rather than silently skipping failed items.

3. **Context Awareness**: Added proper context handling with early cancellation detection.

4. **Idiomatic Go**:
   - Clear variable naming (`succeeded` instead of relying on error state)
   - Proper input validation (`maxRetries < 0` check)
   - Efficient slice pre-allocation using `make([]string, 0, len(items))`
   - Clean error wrapping with `%w` format verb
   - Sleep optimization (no unnecessary sleep after final attempt)

5. **Improved Error Messages**: Contextual error messages that include the item identifier and retry count.

# Go Example Code: Common Usage Patterns

Based on the API surface and overview documentation, here are comprehensive Go examples showing common usage patterns for the `cache` package:

## 1. Basic Cache Operations

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

func main() {
	// Create a cache with 5-minute TTL
	c := cache.New(5 * time.Minute)

	// Store values
	c.Set("user:123", map[string]string{"name": "Alice", "email": "alice@example.com"})
	c.Set("user:456", map[string]string{"name": "Bob", "email": "bob@example.com"})

	// Retrieve values
	if value, ok := c.Get("user:123"); ok {
		user := value.(map[string]string)
		fmt.Printf("Found user: %s (%s)\n", user["name"], user["email"])
	} else {
		fmt.Println("User not found or expired")
	}

	// Update a value
	c.Set("user:123", map[string]string{"name": "Alice Updated", "email": "alice.new@example.com"})

	// Delete a specific key
	c.Delete("user:456")

	// Clear entire cache
	c.Purge()
}
```

## 2. Caching Computation Results (Memoization)

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

func expensiveComputation(n int) int {
	time.Sleep(2 * time.Second) // Simulate expensive operation
	return n * n
}

func cachedComputation(c *cache.Cache, n int) int {
	key := fmt.Sprintf("computation:%d", n)

	// Check cache first
	if cached, ok := c.Get(key); ok {
		fmt.Println("Cache hit!")
		return cached.(int)
	}

	// Compute and cache result
	fmt.Println("Cache miss, computing...")
	result := expensiveComputation(n)
	c.Set(key, result)

	return result
}

func main() {
	c := cache.New(10 * time.Minute)

	fmt.Println(cachedComputation(c, 5)) // Computes: ~2s delay
	fmt.Println(cachedComputation(c, 5)) // From cache: instant
	fmt.Println(cachedComputation(c, 7)) // Computes: ~2s delay
}
```

## 3. Concurrent Access (Goroutines)

```go
package main

import (
	"fmt"
	"sync"
	"time"
	"yourmodule/cache"
)

func main() {
	c := cache.New(5 * time.Minute)
	var wg sync.WaitGroup

	// Multiple writers
	for i := 1; i <= 5; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := 0; j < 10; j++ {
				key := fmt.Sprintf("worker:%d:task:%d", id, j)
				c.Set(key, fmt.Sprintf("result-%d", j))
				time.Sleep(10 * time.Millisecond)
			}
		}(i)
	}

	// Multiple readers
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := 0; j < 50; j++ {
				key := fmt.Sprintf("worker:%d:task:%d", (j%5)+1, j%10)
				if val, ok := c.Get(key); ok {
					fmt.Printf("Reader %d: Got %v\n", id, val)
				}
				time.Sleep(5 * time.Millisecond)
			}
		}(i)
	}

	wg.Wait()
	fmt.Println("All goroutines completed safely")
}
```

## 4. Session Storage Use Case

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

type Session struct {
	UserID    string
	Token     string
	LoginTime time.Time
}

func main() {
	// Short-lived sessions: 15-minute TTL
	sessionCache := cache.New(15 * time.Minute)

	// Store session
	sessionID := "sess_abc123"
	session := Session{
		UserID:    "user_456",
		Token:     "token_xyz789",
		LoginTime: time.Now(),
	}
	sessionCache.Set(sessionID, session)

	// Validate session on next request
	if val, ok := sessionCache.Get(sessionID); ok {
		sess := val.(Session)
		fmt.Printf("Session valid. User: %s\n", sess.UserID)
	} else {
		fmt.Println("Session expired or not found. User must re-authenticate.")
	}

	// Clean up session explicitly
	sessionCache.Delete(sessionID)
}
```

