package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

func main() {
	// Very short TTL for demonstration
	c := cache.New(2 * time.Second)

	c.Set("tempdata", "this will expire soon")

	fmt.Println("t=0s: Setting value")
	if val, ok := c.Get("tempdata"); ok {
		fmt.Printf("t=0s: Retrieved: %v\n", val)
	}

	time.Sleep(1 * time.Second)
	if val, ok := c.Get("tempdata"); ok {
		fmt.Printf("t=1s: Retrieved: %v\n", val)
	}

	time.Sleep(2 * time.Second)
	if val, ok := c.Get("tempdata"); ok {
		fmt.Printf("t=3s: Retrieved: %v\n", val)
