type UserService interface {
    HandleRequest(req Request) Response
}

type DefaultUserService struct {
    validator   Validator
    normalizer  Normalizer
    repository  UserRepository
    notifier    Notifier
    analytics   Analytics
}

func (s *DefaultUserService) HandleRequest(req Request) Response {
    // Validate
    if err := s.validator.Validate(req); err != nil {
        return Response{Error: err.Error()}
    }

    // Normalize
    s.normalizer.Normalize(&req)

    // Persist
    user, err := s.repository.FindOrCreate(req.Name, req.Email)
    if err != nil {
        return Response{Error: err.Error()}
    }
    user.Age = req.Age
    if err := s.repository.Save(user); err != nil {
        return Response{Error: err.Error()}
    }

    // Notify (non-blocking)
    go s.notifier.NotifyUser(user)

    // Track (non-blocking)
    go s.analytics.Track("user_created", user.ID)

    return Response{UserID: user.ID}
}
```

