```go
func (s *DefaultUserService) HandleRequest(req Request) Response {
    // Stage 1: Validate
    if err := s.validator.Validate(req); err != nil {
        return s.errorResponse(err)
    }

    // Stage 2: Normalize
    s.normalizer.Normalize(&req)

    // Stage 3: Persist
    user, err := s.repository.FindOrCreate(req.Name, req.Email)
    if err != nil {
        return s.errorResponse(err)
    }

    user.Age = req.Age
    if err := s.repository.Save(user); err != nil {
        return s.errorResponse(err)
    }

    // Stage 4: Notify (async)
    go s.safeNotify(user)

    // Stage 5: Track (async)
    go s.safeTrack(user.ID)

    return s.successResponse(user.ID)
}

// Helper methods for error handling
func (s *DefaultUserService) errorResponse(err error) Response {
    return Response{Error: err.Error()}
}

func (s *DefaultUserService) successResponse(userID string) Response {
    return Response{UserID: userID}
}

// Safe async operations with panic recovery
func (s *DefaultUserService) safeNotify(user *User) {
    defer func() {
        if r := recover(); r != nil {
            // Log recovery
        }
    }()
    s.notifier.NotifyUser(user)
