package handler

// RequestHandler orchestrates the request processing pipeline
type RequestHandler struct {
	validator   Validator
	normalizer  Normalizer
	repository  UserRepository
	notifier    Notifier
	analytics   Analytics
	logger      Logger // Optional: for error logging
