		validator:   validator,
		normalizer:  normalizer,
		repository:  repository,
		notifier:    notifier,
		analytics:   analytics,
	}
}

// Handle executes the composed pipeline for request processing
func (h *RequestHandler) Handle(req Request) Response {
	// Step 1: Validate Input
	if err := h.validator.Validate(req); err != nil {
		return Response{Error: err.Error()}
	}

	// Step 2: Normalize Data
	h.normalizer.Normalize(&req)

	// Step 3: Create and Persist User
	user := &User{
		Name:  req.Name,
		Email: req.Email,
		Age:   req.Age,
	}
	if err := h.repository.Save(user); err != nil {
		return Response{Error: "failed to create user"}
	}

	// Step 4: Notify User (non-blocking failure)
	if err := h.notifier.Notify(user); err != nil {
		// Continue processing, but flag warning
		return Response{
			UserID:  user.ID,
			Warning: "notification failed",
		}
	}

	// Step 5: Track Analytics (non-blocking failure)
	if err := h.analytics.Track("user_created", user.ID) {
		// Log but don't fail - analytics is best-effort
	}

	// Step 6: Return Success
	return Response{UserID: user.ID}
}
```

