# Security Audit - Remediation Report

Based on the vulnerability analysis, here are specific code fixes for each vulnerability:

---

## Fix 1: Path Traversal (CWE-22) - CRITICAL

**Problem**: Filename not sanitized; attacker can use `../` to write files outside `/uploads`

**Vulnerable Code**:
```go
path := filepath.Join("/uploads", header.Filename)
```

**Fixed Code**:
```go
// Solution: Use filepath.Base() to strip directory components
// and generate a safe filename using UUID

import (
    "github.com/google/uuid"
    "path/filepath"
    "strings"
)

func handleUpload(w http.ResponseWriter, r *http.Request) {
    file, header, _ := r.FormFile("document")
    defer file.Close()

    // Sanitize: Extract only the filename (no path traversal)
    safeFilename := filepath.Base(header.Filename)

    // Better: Generate UUID-based filename with original extension
    ext := filepath.Ext(safeFilename)
    uniqueFilename := uuid.New().String() + ext

    // Construct path safely
    uploadDir := "/uploads"
    path := filepath.Join(uploadDir, uniqueFilename)

    // Verify path stays within upload directory (defense in depth)
    absPath, _ := filepath.Abs(path)
    absUploadDir, _ := filepath.Abs(uploadDir)
    if !strings.HasPrefix(absPath, absUploadDir) {
        http.Error(w, "Invalid file path", http.StatusBadRequest)
        return
    }

    out, _ := os.Create(path)
    defer out.Close()
    io.Copy(out, file)
    fmt.Fprintf(w, "Uploaded to %s", uniqueFilename)
}
```

---

## Fix 2: Unrestricted File Upload (CWE-434) - HIGH

**Problem**: No validation of file type; dangerous executable files can be uploaded

**Fixed Code**:
```go
import (
    "mime"
    "net/http"
)

func isAllowedFileType(filename string, fileHeader *multipart.FileHeader, fileContent io.Reader) bool {
    // Whitelist allowed extensions
    allowedExts := map[string]bool{
        ".pdf":  true,
        ".doc":  true,
        ".docx": true,
        ".txt":  true,
        ".jpg":  true,
        ".png":  true,
    }

    // Check extension
    ext := strings.ToLower(filepath.Ext(filename))
    if !allowedExts[ext] {
        return false
    }

    // Check MIME type
    allowedMimeTypes := map[string]bool{
        "application/pdf":           true,
        "application/msword":        true,
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document": true,
        "text/plain":                true,
        "image/jpeg":                true,
        "image/png":                 true,
    }

    if !allowedMimeTypes[fileHeader.Header.Get("Content-Type")] {
        return false
    }

    // Check magic bytes (first few bytes of file)
    magicBytes := make([]byte, 512)
    n, _ := fileContent.Read(magicBytes)
    detectedMime := http.DetectContentType(magicBytes[:n])

    if !allowedMimeTypes[detectedMime] {
        return false
    }

    return true
}

func handleUpload(w http.ResponseWriter, r *http.Request) {
    file, header, _ := r.FormFile("document")
    defer file.Close()

    // Validate file type
    if !isAllowedFileType(header.Filename, header, file) {
        http.Error(w, "File type not allowed", http.StatusBadRequest)
        return
    }

    // Reset file pointer after validation
    file.Seek(0, 0)

    // ... rest of upload logic with path sanitization (Fix 1)
}
