	filename := filepath.Base(header.Filename)
	if strings.Contains(filename, "..") {
		log.Printf("SECURITY: Path traversal attempt detected: %s", header.Filename)
		http.Error(w, "Invalid filename", http.StatusBadRequest)
		return
	}

	// 4. REMEDIATION: Validate filename length (CWE-400)
	if len(filename) == 0 || len(filename) > maxFilename {
		log.Printf("SECURITY: Invalid filename length: %d", len(filename))
		http.Error(w, "Filename must be between 1 and 255 characters", http.StatusBadRequest)
		return
	}

	// 5. REMEDIATION: Validate file extension (CWE-434)
	ext := strings.ToLower(filepath.Ext(filename))
	if !allowedExtensions[ext] {
		log.Printf("SECURITY: Unauthorized file type attempt: %s", ext)
		http.Error(w, "File type not allowed", http.StatusBadRequest)
		return
	}

	// 6. REMEDIATION: Create upload directory if it doesn't exist (CWE-391)
	if err := os.MkdirAll(uploadDir, 0755); err != nil {
		log.Printf("ERROR: Failed to create upload directory: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}

	// 7. REMEDIATION: Generate unique filename to prevent overwrites (CWE-73)
	// Using timestamp + random suffix to ensure uniqueness
	uniqueFilename := generateUniqueFilename(filename)
	filepath := filepath.Join(uploadDir, uniqueFilename)

	// 8. REMEDIATION: Use O_CREATE|O_EXCL to prevent file overwrite (CWE-73)
	out, err := os.OpenFile(filepath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0644)
	if err != nil {
		log.Printf("ERROR: Failed to create file %s: %v", filepath, err)
		http.Error(w, "Failed to save file", http.StatusInternalServerError)
		return
	}
	defer out.Close()

	// 9. REMEDIATION: Proper error handling for file copy (CWE-391)
	written, err := io.Copy(out, file)
	if err != nil {
		log.Printf("ERROR: Failed to write file: %v", err)
		// Cleanup failed upload
		os.Remove(filepath)
		http.Error(w, "Failed to upload file", http.StatusInternalServerError)
		return
	}

	// 10. REMEDIATION: Validate that file was actually written (CWE-391)
	if written == 0 {
		log.Printf("SECURITY: Empty file upload attempt")
		os.Remove(filepath)
		http.Error(w, "File cannot be empty", http.StatusBadRequest)
		return
	}

	// 11. REMEDIATION: Proper logging and response (CWE-778)
	log.Printf("INFO: File uploaded successfully: %s (original: %s, size: %d bytes)", 
		uniqueFilename, header.Filename, written)
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"status":"success","filename":"%s","size":%d}`, uniqueFilename, written)
}

// Helper function to generate unique filenames
func generateUniqueFilename(originalFilename string) string {
	ext := filepath.Ext(originalFilename)
	name := strings.TrimSuffix(originalFilename, ext)

	// Sanitize name for safety
	name = strings.Map(func(r rune) rune {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || 
		   (r >= '0' && r <= '9') || r == '_' || r == '-' {
			return r
		}
		return '_'
	}, name)

	// Add timestamp for uniqueness
	return fmt.Sprintf("%s_%d%s", name, os.Getpid(), ext)
}
