// AssertSorted verifies the output is in sorted order
func (p *PropertyBasedAssertions) AssertSorted(output []int) {
	for i := 0; i < len(output)-1; i++ {
		if output[i] > output[i+1] {
			p.t.Errorf("[%s] Output not sorted: output[%d]=%d > output[%d]=%d",
				p.name, i, output[i], i+1, output[i+1])
		}
	}
}

// AssertSameLength verifies output has same length as input
func (p *PropertyBasedAssertions) AssertSameLength(input, output []int) {
	if len(input) != len(output) {
		p.t.Errorf("[%s] Length mismatch: input len=%d, output len=%d",
			p.name, len(input), len(output))
	}
}

// AssertSameElements verifies output contains same elements as input
func (p *PropertyBasedAssertions) AssertSameElements(input, output []int) {
	inputCopy := make([]int, len(input))
	copy(inputCopy, input)
	sort.Ints(inputCopy)

	outputCopy := make([]int, len(output))
	copy(outputCopy, output)
	sort.Ints(outputCopy)

	if len(inputCopy) != len(outputCopy) {
		p.t.Errorf("[%s] Element count mismatch: input %d, output %d",
			p.name, len(inputCopy), len(outputCopy))
		return
	}

	for i := 0; i < len(inputCopy); i++ {
		if inputCopy[i] != outputCopy[i] {
			p.t.Errorf("[%s] Elements differ at position %d: input=%d, output=%d",
				p.name, i, inputCopy[i], outputCopy[i])
		}
	}
}

// AssertElementFrequency verifies each element appears same number of times
func (p *PropertyBasedAssertions) AssertElementFrequency(input, output []int) {
	freqInput := make(map[int]int)
	freqOutput := make(map[int]int)

	for _, v := range input {
		freqInput[v]++
	}
	for _, v := range output {
		freqOutput[v]++
	}

	if len(freqInput) != len(freqOutput) {
		p.t.Errorf("[%s] Unique element count mismatch: input %d, output %d",
			p.name, len(freqInput), len(freqOutput))
		return
	}

	for elem, freqIn := range freqInput {
		if freqOut, exists := freqOutput[elem]; !exists || freqIn != freqOut {
			p.t.Errorf("[%s] Frequency mismatch for element %d: input=%d, output=%d",
				p.name, elem, freqIn, freqOut)
		}
	}
